function previewKey(){return [game.pose.x,game.pose.z,game.pose.theta,game.nextBall?.body.id,0,...game.hives.map(h=>h.angle)].join(':');}
const mouth=new T.Line(new T.BufferGeometry(),new T.LineBasicMaterial({color:'#69d5df'}));scene.add(mouth);
