const redCanvas=document.createElement('canvas');redCanvas.width=192;redCanvas.height=72;const redContext=redCanvas.getContext('2d');redContext.fillStyle='#c43b42';redContext.fillRect(0,0,192,72);redContext.fillStyle='#fff';redContext.font='bold 48px Arial';redContext.textAlign='center';redContext.textBaseline='middle';redContext.fillText('RED',96,36);const redTexture=new T.CanvasTexture(redCanvas);redTexture.colorSpace=T.SRGBColorSpace;const redLabel=new T.Sprite(new T.SpriteMaterial({map:redTexture,depthTest:false}));redLabel.name='Red alliance shooter label';redLabel.scale.set(7,2.625,1);redLabel.position.set(0,13,2.6);redLabel.renderOrder=10;robot.add(redLabel);

